-- Emails become case-insensitive at the database level (D30).
--
-- Generated by `prisma migrate dev --create-only`, then the two "AlterTable"
-- blocks were replaced by hand: Prisma knows no cast from varchar to citext and
-- would DROP + re-ADD the column (losing data). Postgres does have the cast, so
-- an in-place type change keeps the rows and the existing unique indexes
-- ("Customer_email_key", "User_email_key" are rebuilt automatically).

-- CreateExtension
CREATE EXTENSION IF NOT EXISTS "citext";

-- AlterTable
ALTER TABLE "Customer" ALTER COLUMN "email" TYPE CITEXT USING "email"::citext;

-- AlterTable
ALTER TABLE "User" ALTER COLUMN "email" TYPE CITEXT USING "email"::citext;
